var GEO = { bulbR: 26, xLoff: 120, xRoff: 175, topY: 70, yB: 340, bulge: 34, w: 9, fw: 7, yEq: 235, scale: 0.16 };

function halo(t) {
  return t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
}

function addFormula(x, y, parts, active) {
  var txt = draw.text('').move(x, y).font({ family: 'Georgia, serif', size: 17, style: 'italic' })
    .fill(active ? '#000' : '#9a9a9a').attr({ 'font-weight': active ? '700' : '400', 'text-anchor': 'middle' });
  var dy = 0;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    var ts = txt.tspan(p.t);
    if (p.sub) { ts.attr({ dy: 4, 'font-size': 11 }); dy = 4; }
    else if (dy) { ts.attr({ dy: -dy }); dy = 0; }
  }
  return txt;
}

function vArrow(x, y1, y2, color) {
  var g = draw.group();
  g.line(x, y1, x, y2).stroke({ color: color, width: 1.4 });
  var s = 5;
  g.polygon([[x, y1], [x - s, y1 + s * 1.6], [x + s, y1 + s * 1.6]]).fill(color);
  g.polygon([[x, y2], [x - s, y2 - s * 1.6], [x + s, y2 - s * 1.6]]).fill(color);
  return g;
}

function drawPanel(idx) {
  var x0 = PANEL_X[idx];
  var g = GEO;
  var xL = x0 + g.xLoff, xR = x0 + g.xRoff;
  var midX = (xL + xR) / 2;
  var active = (idx === state.active);

  // highlight active panel
  if (active) {
    draw.rect(300, 410).move(x0 - 12, 8).fill('#f3f6ff').stroke({ color: '#bcd0f5', width: 1, dasharray: '4,3' }).radius(8).back();
  }

  // h value (mmHg) per configuration
  var hmm;
  if (idx === 0) hmm = state.P;
  else if (idx === 1) hmm = Math.max(0, P_ATM - state.P);
  else hmm = Math.max(0, state.P - P_ATM);
  var hpx = Math.min(hmm, 1000) * g.scale;
  var half = hpx / 2;
  var leftLow = (idx !== 1); // type0 & type2: left meniscus lower
  var leftY = leftLow ? g.yEq + half : g.yEq - half;
  var rightY = leftLow ? g.yEq - half : g.yEq + half;

  var bulbCx = x0 + 40, bulbCy = g.topY;

  // gas (purple) fill: bulb + horizontal connector + left arm above mercury
  draw.circle(g.bulbR * 2).center(bulbCx, bulbCy).fill('#e7e1f2').stroke('#9a90b0', 1.4);
  draw.rect((xL - bulbCx), g.fw * 2).move(bulbCx, g.topY - g.fw).fill('#e7e1f2');
  draw.rect(g.fw * 2, Math.max(0, leftY - g.topY)).move(xL - g.fw, g.topY).fill('#e7e1f2');

  // mercury (gray): left column, right column, bottom
  var hg = '#b3b3b3', hs = '#8c8c8c';
  draw.rect(g.fw * 2, Math.max(0, g.yB - leftY)).move(xL - g.fw, leftY).fill(hg);
  draw.rect(g.fw * 2, Math.max(0, g.yB - rightY)).move(xR - g.fw, rightY).fill(hg);
  draw.rect((xR - xL) + g.fw * 2, g.bulge * 0.7 + 4).move(xL - g.fw, g.yB - 2).fill(hg);
  draw.ellipse((xR - xL) + g.fw * 2, g.bulge).center(midX, g.yB + g.bulge * 0.35).fill(hg);

  // glass outline (U)
  var topYL = g.topY, topYR = g.topY;
  var d = 'M ' + (xL - g.w) + ' ' + topYL + ' L ' + (xL - g.w) + ' ' + g.yB +
    ' Q ' + midX + ' ' + (g.yB + g.bulge) + ' ' + (xR + g.w) + ' ' + g.yB +
    ' L ' + (xR + g.w) + ' ' + topYR;
  draw.path(d).fill('none').stroke({ color: hs, width: 2, linecap: 'round' });
  // left arm inner edge hint
  draw.line(xL + g.w, g.topY, xL + g.w, g.yB - 4).stroke({ color: hs, width: 1, opacity: 0.5 });
  draw.line(xR - g.w, g.topY, xR - g.w, g.yB - 4).stroke({ color: hs, width: 1, opacity: 0.5 });

  // right arm top: closed cap or open
  if (idx === 0) {
    draw.path('M ' + (xR - g.w) + ' ' + g.topY + ' Q ' + xR + ' ' + (g.topY - 12) + ' ' + (xR + g.w) + ' ' + g.topY)
      .fill('none').stroke({ color: hs, width: 2 });
    var vac = draw.text('Vacuum').center(xR + 4, g.topY + 55).font({ size: 12, family: 'sans-serif' }).fill('#555');
    halo(vac);
    var ce = draw.text('Closed end').move(xR + 18, g.topY - 28).font({ size: 12, family: 'sans-serif' }).fill('#222');
    halo(ce);
    draw.line(xR + 16, g.topY - 18, xR + 2, g.topY - 6).stroke({ color: '#222', width: 1 });
  } else {
    var oe = draw.text('Open end').move(xR + 18, g.topY - 6).font({ size: 12, family: 'sans-serif' }).fill('#222');
    halo(oe);
    draw.line(xR + 16, g.topY - 2, xR + 4, g.topY + 2).stroke({ color: '#222', width: 1 });
    // P_atm downward arrow
    draw.line(xR, g.topY - 50, xR, g.topY - 14).stroke({ color: '#000', width: 1.6 });
    draw.polygon([[xR, g.topY - 10], [xR - 5, g.topY - 20], [xR + 5, g.topY - 20]]).fill('#000');
    var pa = draw.text('').move(xR - 4, g.topY - 70).font({ family: 'Georgia, serif', size: 15, style: 'italic' }).fill('#000');
    pa.tspan('P'); pa.tspan('atm').attr({ dy: 4, 'font-size': 10 });
  }

  // stopcock symbol on connector
  var scx = bulbCx + 38;
  draw.line(scx, g.topY - 14, scx, g.topY + 14).stroke({ color: '#777', width: 2 });
  draw.ellipse(20, 7).center(scx, g.topY - 12).fill('#cfc8dd').stroke('#777', 1);
  draw.circle(6).center(scx, g.topY - 12).fill('#777');

  // Gas label
  var gl = draw.text('Gas').center(bulbCx, bulbCy).font({ size: 13, family: 'sans-serif' }).fill('#333');

  // h double arrow + ticks (right side)
  var ax = xR + 30;
