axisG.line(X(2), Y0, X(2), Y0 - 18).stroke({ color: AXIS, width: 2 });

txt('−2', X(-2) - 10, Y0 + 16, 35, 'middle');
txt('0', X0 + 18, Y0 + 16, 35, 'middle');
txt('2', X(2), Y0 + 16, 35, 'middle');
