function addFormula(cx, y, parts, active) {
  var widths = [], total = 0;
  for (var i = 0; i < parts.length; i++) {
    var w = termWidth(parts[i].t, parts[i].sub);
    widths.push(w); total += w;
  }
  var x = cx - total / 2;
  var col = active ? '#000' : '#9a9a9a';
  var g = draw.group();
  for (var j = 0; j < parts.length; j++) {
