    narration: 'With the right arm sealed and evacuated, the only force on the closed-arm meniscus is the gas pressure, so the height h alone balances it: P_gas = hρg. Drag the slider and watch h grow in direct proportion to P_gas.',
    type: 0, P: 500 },
  { title: 'Open-end, gas below atmosphere',
    narration: 'Now the open arm feels P_atm. The gas side stands higher, meaning the atmosphere is winning, so P_gas = P_atm − hρg. As you raise P_gas toward 760 mmHg the height difference h collapses to zero.',
    type: 1, P: 500 },
  { title: 'Open-end, gas above atmosphere',
    narration: 'Push P_gas above 760 mmHg and the open-arm liquid is driven higher instead: the gas is winning, so P_gas = P_atm + hρg. The same instrument reads both sub- and super-atmospheric pressures; only the sign in front of hρg changes.',
    type: 2, P: 900 },
  { title: 'Derive the formula',
    narration: 'Click the h arrow in any panel to step through the equal-pressure-at-equal-depth argument. All three formulas are the same hydrostatic balance evaluated against a different reference pressure (vacuum = 0, or P_atm on the higher or lower side).',
    type: 2, P: 900 }
];
var curStep = 0;

function applyStep(i) {
  curStep = i;
  var s = steps[i];
  state.active = s.type;
  state.P = s.P;
  for (var k = 0; k < 3; k++) {
    var b = document.getElementById('typeBtn' + k);
    if (b) b.className = (k === s.type) ? 'active' : '';
  }
  var sl = document.getElementById('gasPressureInput');
  if (sl) sl.value = s.P;
  var ov = document.getElementById('gasPressureVal');
  if (ov) ov.value = s.P;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = s.narration;
  var lbl = document.getElementById('stepLabel');
  if (lbl) lbl.textContent = (i + 1) + '/' + steps.length;
  redraw();
}
function nextStep() { applyStep((curStep + 1) % steps.length); }
function prevStep() { applyStep((curStep - 1 + steps.length) % steps.length); }

redraw();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

