Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label style="font-weight:600">Manometer configuration</label>
<div style="display:flex;flex-direction:column;gap:2px">
  <button id="typeBtn0" class="active" onclick="setManometerType(0)">Closed-end (vacuum)</button>
  <button id="typeBtn1" onclick="setManometerType(1)">Open-end: gas lower</button>
  <button id="typeBtn2" onclick="setManometerType(2)">Open-end: gas higher</button>
</div>
<label>Gas pressure P<sub>gas</sub> (mmHg): <output id="gasPressureVal">500</output>
  <input id="gasPressureInput" type="range" min="0" max="1200" step="10" value="500"
    oninput="document.getElementById('gasPressureVal').value=this.value;update_gasPressure(+this.value)">
</label>
<hr style="border:0;border-top:1px solid #ddd;margin:2px 0">
<p id="demoNarration" style="margin:0;font-size:11px;max-width:210px;line-height:1.35"></p>
<div style="display:flex;align-items:center;gap:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px"></span>
  <button onclick="nextStep()">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1000, H = 480;
draw.viewbox(0, 0, W, H);

var P_ATM = 760;
var state = { active: 0, P: 500 };

var PANEL_X = [18, 345, 672];
var GEO = { bulbR: 26, xLoff: 115, xRoff: 183, topY: 88, yB: 330, bulge: 40,
            outerW: 17, innerW: 11, yEq: 230, scale: 0.16 };

function halo(t) {
  return t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
}

function termWidth(t, sub) {
  var e = draw.text(t).font({ family: 'Georgia, serif', size: sub ? 12 : 19, style: 'italic' }).move(-3000, -3000);
  var w = e.bbox().width;
  e.remove();
  return w;
}

function addFormula(cx, y, parts, active) {
  var widths = [], total = 0;
  for (var i = 0; i < parts.length; i++) {
    var w = termWidth(parts[i].t, parts[i].sub);
    widths.push(w); total += w;
  }
  var x = cx - total / 2;
  var col = active ? '#000' : '#9a9a9a';
  var g = draw.group();
  for (var j = 0; j < parts.length; j++) {
    var p = parts[j];
    var ts = g.text(p.t).font({ family: 'Georgia, serif', size: p.sub ? 12 : 19, style: 'italic' })
      .fill(col).attr({ 'font-weight': active ? '700' : '400' });
    ts.move(x, p.sub ? y + 5 : y);
    x += widths[j];
  }
  if (active) {
    g.line(cx - total / 2 - 4, y + 24, cx + total / 2 + 4, y + 24)
      .stroke({ color: '#4a90d9', width: 2 });
  }
  return g;
}

function vArrow(x, y1, y2, color) {
  var g = draw.group();
  g.line(x, y1, x, y2).stroke({ color: color, width: 1.5 });
  var s = 5;
  g.polygon([[x, y1], [x - s, y1 + s * 1.6], [x + s, y1 + s * 1.6]]).fill(color);
  g.polygon([[x, y2], [x - s, y2 - s * 1.6], [x + s, y2 - s * 1.6]]).fill(color);
  return g;
}

function drawPanel(idx) {
  var x0 = PANEL_X[idx];
  var g = GEO;
  var xL = x0 + g.xLoff, xR = x0 + g.xRoff;
  var midX = (xL + xR) / 2;
  var active = (idx === state.active);

  var hmm;
  if (idx === 0) hmm = state.P;
  else if (idx === 1) hmm = Math.max(0, P_ATM - state.P);
  else hmm = Math.max(0, state.P - P_ATM);
  var hpx = Math.min(hmm * g.scale, 190);
  /* Clamp minimum visible arrow height */
  if (hmm > 0 && hpx < 14) hpx = 14;
  var half = hpx / 2;
  var leftLow = (idx !== 1);
  var leftY = leftLow ? g.yEq + half : g.yEq - half;
  var rightY = leftLow ? g.yEq - half : g.yEq + half;

  var bulbCx = x0 + 42, bulbCy = g.topY;

  /* ---- glass tube as centreline strokes (smooth U-bend) ---- */
  var bend = 'M ' + xL + ' ' + g.topY + ' L ' + xL + ' ' + g.yB +
    ' Q ' + midX + ' ' + (g.yB + g.bulge) + ' ' + xR + ' ' + g.yB +
    ' L ' + xR + ' ' + g.topY;
  draw.path(bend).fill('none').stroke({ color: '#9a9a9a', width: g.outerW, linecap: 'round', linejoin: 'round' });
  draw.path(bend).fill('none').stroke({ color: '#ffffff', width: g.innerW, linecap: 'round', linejoin: 'round' });

  /* ---- gas (purple): bulb + connector + left arm above mercury ---- */
  var gasC = '#e7e1f2', gasS = '#9a90b0';
  draw.line(bulbCx, g.topY, xL, g.topY).stroke({ color: gasC, width: g.innerW, linecap: 'round' });
  draw.line(xL, g.topY, xL, leftY).stroke({ color: gasC, width: g.innerW, linecap: 'round' });
  draw.circle(g.bulbR * 2).center(bulbCx, bulbCy).fill(gasC).stroke(gasS, 1.5);

  /* ---- mercury (gray) centreline from left meniscus around bend to right meniscus ---- */
  var merc = 'M ' + xL + ' ' + leftY + ' L ' + xL + ' ' + g.yB +
    ' Q ' + midX + ' ' + (g.yB + g.bulge) + ' ' + xR + ' ' + g.yB +
    ' L ' + xR + ' ' + rightY;
  draw.path(merc).fill('none').stroke({ color: '#b3b3b3', width: g.innerW, linecap: 'round', linejoin: 'round' });

  /* ---- crisp glass outline on top ---- */
  draw.path(bend).fill('none').stroke({ color: '#8c8c8c', width: 1.6, linecap: 'round', linejoin: 'round' });

  /* ---- right arm top: closed cap or open ---- */
  if (idx === 0) {
    draw.path('M ' + (xR - g.outerW / 2) + ' ' + g.topY + ' Q ' + xR + ' ' + (g.topY - 14) + ' ' + (xR + g.outerW / 2) + ' ' + g.topY)
      .fill('#fff').stroke({ color: '#8c8c8c', width: 1.6 });
    var vac = draw.text('Vacuum').center(xR - 2, g.topY + 62).font({ size: 14, family: 'sans-serif' }).fill('#555');
    halo(vac);
    var ce = draw.text('Closed end').move(xR + 16, g.topY - 30).font({ size: 14, family: 'sans-serif' }).fill('#111');
    halo(ce);
    draw.line(xR + 14, g.topY - 20, xR + 2, g.topY - 8).stroke({ color: '#111', width: 1.1 });
  } else {
    var oe = draw.text('Open end').move(xR + 16, g.topY - 4).font({ size: 14, family: 'sans-serif' }).fill('#111');
    halo(oe);
    draw.line(xR + 14, g.topY, xR + 4, g.topY + 2).stroke({ color: '#111', width: 1.1 });
    /* Downward arrow for P_atm */
    draw.line(xR, g.topY - 50, xR, g.topY - 16).stroke({ color: '#000', width: 1.7 });
    draw.polygon([[xR, g.topY - 12], [xR - 5, g.topY - 22], [xR + 5, g.topY - 22]]).fill('#000');
    /* P_atm label: full-size P with subscript atm */
    var paG = draw.group();
    var pMain = paG.text('P').font({ family: 'Georgia, serif', size: 19, style: 'italic' }).fill('#000');
    pMain.move(xR - 14, g.topY - 76);
    var pSub = paG.text('atm').font({ family: 'Georgia, serif', size: 12, style: 'italic' }).fill('#000');
    pSub.move(xR - 14 + pMain.bbox().width, g.topY - 70);
  }

  /* ---- stopcock symbol on connector ---- */
  var scx = bulbCx + 40;
  draw.line(scx, g.topY - 15, scx, g.topY + 15).stroke({ color: '#777', width: 2 });
  draw.ellipse(22, 8).center(scx, g.topY - 13).fill('#cfc8dd').stroke('#777', 1);
  draw.circle(6).center(scx, g.topY - 13).fill('#777');

  /* ---- Gas label ---- */
  var gl = draw.text('Gas').center(bulbCx, bulbCy).font({ size: 14, family: 'sans-serif' }).fill('#333');

  /* ---- h double arrow + meniscus ticks ---- */
  var ax = xR + 32;
  var yTop = Math.min(leftY, rightY), yBot = Math.max(leftY, rightY);
  draw.line(xR + g.innerW / 2, leftY, ax + 8, leftY).stroke({ color: '#000', width: 1 });
  draw.line(xR + g.innerW / 2, rightY, ax + 8, rightY).stroke({ color: '#000', width: 1 });
  if (half > 3) {
    var arr = vArrow(ax, yTop, yBot, '#000');
    arr.css('cursor', 'pointer');
    arr.on('click', function () { showDerivation(idx); });
    arr.on('mousemove', function (e) { showTooltip('Click to derive this formula', e); });
    arr.on('mouseleave', hideTooltip);
  }
  var hl = draw.text('h').move(ax + 7, (yTop + yBot) / 2 - 9).font({ family: 'Georgia, serif', size: 17, style: 'italic' }).fill('#000');
  halo(hl);

  /* ---- formula ---- */
  var parts;
  if (idx === 0) parts = [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = hρg' }];
  else if (idx === 1) parts = [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = P' }, { t: 'atm', sub: 1 }, { t: ' − hρg' }];
  else parts = [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = P' }, { t: 'atm', sub: 1 }, { t: ' + hρg' }];
  addFormula(x0 + 132, 428, parts, active);

  /* ---- hover on bulb ---- */
  draw.circle(g.bulbR * 2).center(bulbCx, bulbCy).fill('transparent').css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Gas bulb: unknown pressure P_gas', e); })
    .on('mouseleave', hideTooltip);
}

function showDerivation(idx) {
  var body;
  if (idx === 0) {
    body = 'At the level of the lower (gas-side) meniscus, pressure in the connected liquid must be equal in both arms. Gas side: P_gas. Closed side at that same depth: vacuum (0) plus the liquid column hρg above it. Equating: P_gas = hρg. The reference pressure is zero, so h alone measures the gas pressure.';
  } else if (idx === 1) {
    body = 'Take the horizontal level of the lower meniscus (here on the open side). Open side at that level: P_atm. Gas side at the same depth: P_gas plus the extra liquid hρg standing above it on the gas side. Equating: P_atm = P_gas + hρg, i.e. P_gas = P_atm − hρg. The atmosphere is the higher reference, so hρg subtracts.';
  } else {
    body = 'Take the horizontal level of the lower meniscus (here on the gas side). Gas side at that level: P_gas. Open side at the same depth: P_atm plus the extra liquid hρg standing above it on the open side. Equating: P_gas = P_atm + hρg. The gas is the higher pressure, so hρg adds.';
  }
  showPopup('Hydrostatic balance — panel ' + (idx + 1), body);
}

function redraw() {
  draw.clear();
  for (var i = 0; i < 3; i++) drawPanel(i);
}

function setManometerType(idx) {
  state.active = idx;
  for (var i = 0; i < 3; i++) {
    var b = document.getElementById('typeBtn' + i);
    if (b) b.className = (i === idx) ? 'active' : '';
  }
  redraw();
}

function update_gasPressure(v) {
  state.P = v;
  redraw();
}

/* ---- demo step player ---- */
var steps = [
  { title: 'Closed-end: vacuum reference',
    narration: 'With the right arm sealed and evacuated, the only force on the closed-arm meniscus is the gas pressure, so the height h alone balances it: P_gas = hρg. Drag the slider and watch h grow in direct proportion to P_gas.',
    type: 0, P: 500 },
  { title: 'Open-end, gas below atmosphere',
    narration: 'Now the open arm feels P_atm. The gas side stands higher, meaning the atmosphere is winning, so P_gas = P_atm − hρg. As you raise P_gas toward 760 mmHg the height difference h collapses to zero.',
    type: 1, P: 500 },
  { title: 'Open-end, gas above atmosphere',
    narration: 'Push P_gas above 760 mmHg and the open-arm liquid is driven higher instead: the gas is winning, so P_gas = P_atm + hρg. The same instrument reads both sub- and super-atmospheric pressures; only the sign in front of hρg changes.',
    type: 2, P: 900 },
  { title: 'Derive the formula',
    narration: 'Click the h arrow in any panel to step through the equal-pressure-at-equal-depth argument. All three formulas are the same hydrostatic balance evaluated against a different reference pressure (vacuum = 0, or P_atm on the higher or lower side).',
    type: 2, P: 900 }
];
var curStep = 0;

function applyStep(i) {
  curStep = i;
  var s = steps[i];
  state.active = s.type;
  state.P = s.P;
  for (var k = 0; k < 3; k++) {
    var b = document.getElementById('typeBtn' + k);
    if (b) b.className = (k === s.type) ? 'active' : '';
  }
  var sl = document.getElementById('gasPressureInput');
  if (sl) sl.value = s.P;
  var ov = document.getElementById('gasPressureVal');
  if (ov) ov.value = s.P;
  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = s.narration;
  var lbl = document.getElementById('stepLabel');
  if (lbl) lbl.textContent = (i + 1) + '/' + steps.length;
  redraw();
}
function nextStep() { applyStep((curStep + 1) % steps.length); }
function prevStep() { applyStep((curStep - 1 + steps.length) % steps.length); }

redraw();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

